"""TOY-S VARIANT (Nov 19 2026): S mass term 4s -> 1s (stone toy: S mass^2 = 1 + 1.5 d^2). Everything else as pumping_core_expansion_v1.py. Generated by sed-like replacement; 2 replacements."""
"""RESEARCH ONLY. Pumping under expansion, homogeneous 2-DOF core with Hubble friction (run request v2, coordination log Nov 18 2026).
V = 2 s^2 + s^4/8 + (3/4) s^2 d^2 - d^2/2 + d^4/8 (#523). s'' = -3H s' - (4s + s^3/2 + 1.5 s d^2); d'' = -3H d' + d - d^3/2 - 1.5 s^2 d - kk d.
x = peak s^2 per S period (x = A^2, n = x/2); band exit when x < 4/3 (D tachyonic below). kk = k^2 of an optional finite-k D mode (0 = the core)."""
import math, numpy as np
from scipy.integrate import solve_ivp
XEXIT = 4.0 / 3.0
def rhs(H, kk, frozen):
    def f(t, y):
        s, d, ps, pd = y
        if frozen:                                           # S prescribed: s = A cos(w t), no friction, no back-reaction
            return [ps, pd, -(1 * s + 0.5 * s ** 3), -3 * H * pd + d - 0.5 * d ** 3 - 1.5 * s * s * d - kk * d]
        return [ps, pd, -3 * H * ps - (1 * s + 0.5 * s ** 3 + 1.5 * s * d * d),
                -3 * H * pd + d - 0.5 * d ** 3 - 1.5 * s * s * d - kk * d]
    return f
def sim(H, x0, d0, T=60.0, kk=0.0, frozen=False, texit_fixed=None, dtout=0.05):
    A = math.sqrt(x0); f = rhs(H, kk, frozen)
    t = np.arange(0, T, dtout)
    sol = solve_ivp(f, (0, T), [A, d0, 0.0, 0.0], method="DOP853", rtol=1e-10, atol=1e-30, t_eval=t)
    s, d = sol.y[0], sol.y[1]; w = int(round(3.2 / dtout))            # window = one S period (omega_S ~ 2: pi)
    sm = np.array([np.max(np.abs(s[max(0, i - w):i + 1])) ** 2 for i in range(len(t))])
    dm = np.array([np.max(np.abs(d[max(0, i - w):i + 1])) for i in range(len(t))])
    inband = sm >= XEXIT
    if frozen: texit = texit_fixed
    else:
        idx = np.nonzero(~inband & (t > 3.2))[0]; texit = float(t[idx[0]]) if idx.size else T
    return t, sm, dm, texit
def sigma(t, dm, t0, t1):
    m = (t >= t0) & (t <= t1) & (dm > 0)
    return float(np.polyfit(t[m], np.log(dm[m]), 1)[0]) if m.sum() > 5 else float("nan")
if __name__ == "__main__":
    print("exploratory R3: H=0, tiny D (1e-8), sigma over t in [10, 50] vs x0 (k=0 core)")
    for x0 in (1.4, 1.6, 2.0, 2.4, 2.67):
        t, sm, dm, te = sim(0.0, x0, 1e-8, T=60.0)
        print(f"  x0 {x0}: sigma {sigma(t, dm, 10, 50):+.4f}  D max {dm[-1]:.2e}", flush=True)

def main_grid():
    Hs = (0.0, 0.003, 0.0057, 0.01, 0.02, 0.03, 0.05, 0.11, 0.15, 0.25)
    print("MAIN (k=0 core, S and D both with friction): G = max|d|(t_exit)/d0; sigma over [3.2, min(t_exit,30)]")
    print("  x0   d0      " + " ".join(f"H={h:<6g}" for h in Hs))
    for x0 in (1.6, 2.0, 2.67):
        for d0 in (1e-8, 1e-3, 1e-1):
            row = []
            for H in Hs:
                t, sm, dm, te = sim(H, x0, d0, T=100.0)
                i = int(np.searchsorted(t, te)); i = min(i, len(t) - 1)
                row.append(f"{dm[i] / d0:8.3g}")
            print(f"  {x0:<4} {d0:<7g} " + " ".join(row), flush=True)
    print("  (t_exit, x0=2.0): " + ", ".join(f"H={h}: {sim(h,2.0,1e-8,T=100.0)[3]:.1f}" for h in Hs[1:]))
    print("C1 frozen S (no S friction, no back-reaction), d0=1e-1 vs 1e-8, sigma over [3.2, 30], H=0 and 0.0057:")
    for H in (0.0, 0.0057):
        for d0 in (1e-8, 1e-1):
            t, sm, dm, te = sim(H, 2.0, d0, T=30.0, frozen=True, texit_fixed=30.0)
            print(f"  H {H} d0 {d0:g}: sigma {sigma(t, dm, 3.2, 30):+.4f}")
def kmode_scan():
    print("EXTENSION (not in the approved design; exploratory, H=0, tiny D): finite-k mode, kk scanned around resonance kk_res = 5 - 0.375 x")
    for x0 in (1.6, 2.0, 2.67):
        best = (-9, None)
        for dk in np.linspace(-1.2, 1.2, 25):
            kk = 5 - 0.375 * x0 + dk
            t, sm, dm, te = sim(0.0, x0, 1e-8, T=60.0, kk=kk)
            sg = sigma(t, dm, 10, 50)
            if sg > best[0]: best = (sg, kk)
        print(f"  x0 {x0}: max sigma {best[0]:+.4f} at kk {best[1]:.3f} (k {math.sqrt(max(best[1],0)):.3f})", flush=True)
if __name__ == "__main__" and len(__import__("sys").argv) > 1:
    main_grid(); kmode_scan()
